import click, pathlib
from click.testing import CliRunner

def test_probe():
    class Sub(str):
        pass
    assert click.Option(['-a','x'], flag_value=Sub('q')).type is click.STRING
    assert click.Option(['-b','x'], flag_value=3.5).type is click.FLOAT
    assert click.Option(['-c','x'], flag_value=(1,2)).type is not click.UNPROCESSED
    p = pathlib.Path('/tmp')
    o = click.Option(['-d','x'], flag_value=p)
    assert o.type is click.UNPROCESSED

    @click.command()
    @click.option('--a','v',flag_value=p)
    @click.option('--b','v',flag_value=b'x')
    def cli(v):
        click.echo(repr(v), nl=False)
    r = CliRunner()
    assert r.invoke(cli, ['--a']).output == repr(p)
    assert r.invoke(cli, ['--b']).output == repr(b'x')
    assert r.invoke(cli, []).exit_code == 0

