import click
from click.testing import CliRunner


def run(cli, args):
    return CliRunner().invoke(cli, args)


def test_neg_bool_flag():
    @click.command()
    @click.option('--foo', is_flag=True, flag_value=False, default=True)
    def cli(foo):
        click.echo(repr(foo), nl=False)

    assert run(cli, []).output == 'True'
    assert run(cli, ['--foo']).output == 'False'


def test_nonbool_flag_default_true_sentinel():
    @click.command()
    @click.option('--upper', 'mode', flag_value='upper', default=True)
    @click.option('--lower', 'mode', flag_value='lower')
    def cli(mode):
        click.echo(repr(mode), nl=False)

    assert run(cli, []).output == "'upper'"
    assert run(cli, ['--lower']).output == "'lower'"


def test_single_flag_default_true():
    @click.command()
    @click.option('--foo', is_flag=True, default=True)
    def cli(foo):
        click.echo(repr(foo), nl=False)

    assert run(cli, []).output == 'True'
    assert run(cli, ['--foo']).output == 'True'

import click


def _ctx():
    return click.Context(click.Command('c'))


def test_get_default_bool_flag_literal():
    opt = click.Option(['--foo'], is_flag=True, flag_value=False, default=True)
    assert opt.is_bool_flag
    assert opt.get_default(_ctx()) is True


def test_get_default_bool_pair_literal():
    opt = click.Option(['--foo/--no-foo'], default=True)
    assert opt.get_default(_ctx()) is True
    opt = click.Option(['--foo/--no-foo'], default=None)
    assert opt.get_default(_ctx()) is None


def test_get_default_nonbool_sentinel():
    opt = click.Option(['--up'], flag_value='upper', default=True)
    assert not opt.is_bool_flag
    assert opt.get_default(_ctx()) == 'upper'


def test_get_default_callable_flag_value_not_called():
    class Foo:
        pass
    opt = click.Option(['--up'], flag_value=Foo, default=True)
    assert opt.get_default(_ctx(), call=False) is Foo

import click
from click.core import Context


def _ctx():
    return Context(click.Command('x'))


def test_bool_flag_default_true_literal():
    o = click.Option(['--f'], is_flag=True, default=True, flag_value=False)
    assert o.is_bool_flag
    assert o.get_default(_ctx()) is True


def test_nonbool_flag_default_true_sentinel():
    o = click.Option(['--f'], flag_value='upper', default=True)
    assert not o.is_bool_flag
    assert o.get_default(_ctx()) == 'upper'


def test_callable_flag_value_not_called():
    class K:
        pass
    o = click.Option(['--f'], flag_value=K, default=True)
    assert o.get_default(_ctx(), call=True) is K


def test_pair_default_true_no_flag():
    o = click.Option(['--f/--no-f'], default=True)
    assert o.get_default(_ctx()) is True

import click
from click.testing import CliRunner


def run(cli, args=()):
    return CliRunner().invoke(cli, list(args))


def test_nonbool_default_true_resolves():
    @click.command()
    @click.option('--upper', 'mode', flag_value='upper', default=True)
    @click.option('--lower', 'mode', flag_value='lower')
    def cli(mode):
        click.echo(repr(mode), nl=False)

    assert run(cli).output == repr('upper')
    assert run(cli, ['--lower']).output == repr('lower')


def test_bool_flag_value_false_default_true():
    @click.command()
    @click.option('--f', flag_value=False, default=True, type=bool)
    def cli(f):
        click.echo(repr(f), nl=False)

    assert run(cli).output == 'True'
    assert run(cli, ['--f']).output == 'False'


def test_callable_flag_value_default_true():
    class A:
        pass

    @click.command()
    @click.option('--a', 'k', flag_value=A, default=True)
    def cli(k):
        click.echo(k.__name__ if isinstance(k, type) else 'inst', nl=False)

    assert run(cli).output in ('A', 'inst')


def test_get_default_direct():
    opt = click.Option(['--x'], flag_value='v', default=True)
    ctx = click.Context(click.Command('c'))
    assert opt.get_default(ctx) == 'v'

